#include <string_view>
#include <vector>

std::size_t countOf(std::string_view text, char c)
{
    std::size_t n{ 0 };
    for (char ch : text) if (ch == c) ++n;
    return n;
}

std::size_t countOf(std::string_view text, std::string_view word)
{
    if (word.empty()) return text.size() + 1;
    std::size_t n{ 0 };
    for (std::size_t at{ text.find(word) }; at != std::string_view::npos; at = text.find(word, at + word.size())) ++n;
    return n;
}

std::size_t countOf(const std::vector<int>& values, int value)
{
    std::size_t n{ 0 };
    for (int x : values) if (x == value) ++n;
    return n;
}

template<class Pred>
std::size_t countOf(const std::vector<int>& values, Pred pred)
{
    std::size_t n{ 0 };
    for (int x : values) if (pred(x)) ++n;
    return n;
}

unitTests:
TEST("characters") {
    CHECK_EQ(countOf("reference", 'e'), 4u);
    CHECK_EQ(countOf("reference", 'z'), 0u);
    CHECK_EQ(countOf("", 'a'), 0u);
}
TEST("words do not overlap") {
    CHECK_EQ(countOf("aaaa", "aa"), 2u);
    CHECK_EQ(countOf("the cat and the hat", "the"), 2u);
    CHECK_EQ(countOf("abababa", "aba"), 2u);
    CHECK_EQ(countOf("abc", "abcd"), 0u);
    CHECK_EQ(countOf("a", std::string_view("a")), 1u);
}
TEST("the empty word") {
    CHECK_EQ(countOf("abc", ""), 4u);
    CHECK_EQ(countOf("", ""), 1u);
}
TEST("values and predicates") {
    const std::vector<int> v{ 3, 1, 3, 3, 7, -3 };
    CHECK_EQ(countOf(v, 3), 3u);
    CHECK_EQ(countOf(v, 9), 0u);
    CHECK_EQ(countOf(v, [](int x) { return x < 0; }), 1u);
    CHECK_EQ(countOf(v, [](int x) { return x % 2 != 0; }), 6u);
    int calls{ 0 };
    countOf(v, [&](int) { ++calls; return false; });
    CHECK_EQ(calls, 6);
    CHECK_EQ(countOf(std::vector<int>{}, 1), 0u);
}

